shaders.source:
struct Uniforms {
  mvp : mat4x4<f32>,
  normalMatrix : mat3x3<f32>,
  ink : vec3<f32>,
  glow : vec3<f32>,
  gain : f32,
  time : f32,
};
@group(0) @binding(0) var<uniform> u : Uniforms;

struct VertexInput {
  @location(0) position : vec3<f32>,
  @location(1) uv : vec2<f32>,
};

struct VertexOutput {
  @builtin(position) position : vec4<f32>,
  @location(0) vUv : vec2<f32>,
};

@vertex
fn vertexMain(in : VertexInput) -> VertexOutput {
  var out : VertexOutput;
  out.vUv = in.uv;
  out.position = (u.mvp * vec4<f32>(in.position, 1.0));
  return out;
}

@fragment
fn fragmentMain(in : VertexOutput) -> @location(0) vec4<f32> {
  let coord = in.vUv;
  let drift = (u.time * 0.65);
  let wave = ((sin((((coord.x * 12.0) + (sin(((coord.y * 5.0) + drift)) * 2.0)) + drift)) * 0.5) + 0.5);
  let ribbon = pow(wave, 5.0);
  return vec4<f32>(mix(u.ink, u.glow, clamp((ribbon * u.gain), 0.0, 1.0)), 1.0);
}

shaders.vertex:
#version 300 es
in vec3 position;
in vec2 uv;
uniform mat4 mvp;
uniform mat3 normalMatrix;
uniform vec3 ink;
uniform vec3 glow;
uniform float gain;
uniform float time;
out vec2 vUv;

void main() {
  vUv = uv;
  gl_Position = (mvp * vec4(position, 1.0));
}

shaders.fragment:
#version 300 es
precision highp float;
uniform mat4 mvp;
uniform mat3 normalMatrix;
uniform vec3 ink;
uniform vec3 glow;
uniform float gain;
uniform float time;
in vec2 vUv;
out vec4 fragColor;

void main() {
  vec2 coord = vUv;
  float drift = (time * 0.65);
  float wave = ((sin((((coord.x * 12.0) + (sin(((coord.y * 5.0) + drift)) * 2.0)) + drift)) * 0.5) + 0.5);
  float ribbon = pow(wave, 5.0);
  fragColor = vec4(mix(ink, glow, clamp((ribbon * gain), 0.0, 1.0)), 1.0);
}
